-- mvtk/tiled/spawners/bosses.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local parse_drops_string = H.parse_drops_string
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local resolve_difficulty_scaling = H.resolve_difficulty_scaling
    local print = H.print
    local polyline_registry = H.polyline_registry

    local function optional_id(value)
        local id = non_empty_string(value)
        return id == "none" and nil or id
    end

function handlers.boss(object, room_id)
    local props = get_props(object)
    local boss_id = make_id(props, "boss_id", "boss", object, room_id)
    local boss_preset = resolve_boss_preset(props)
    local boss_name = resolve_boss_display_name(object, props, boss_id)
    if boss_id == non_empty_string(object.name) and non_empty_string(props.boss_tag) then
        boss_id = props.boss_tag
    end
    local world_x, world_y, pos = world_point(object, room_id)

    props.boss_name = boss_name
    if boss_preset then
        props.boss_preset = boss_preset
        props.boss_type = boss_preset
    end

    msg.post("main:/main_go#script", hash("register_boss_spawn"), {
        id = boss_id,
        boss_tag = OP.get(props, "boss_id"),
        boss_name = boss_name,
        boss_preset = boss_preset or "",
        boss_type = boss_preset or "",
        position = pos,
        room_id = room_id,
        intro_cutscene = props.intro_cutscene,
        arena_lock = to_bool(props.arena_lock, true),
        show_health_bar = to_bool(props.show_health_bar, true),
        health_bar_position = props.health_bar_position or "",
        phase_config = props.phase_config,
        boss_health = tonumber(props.boss_health) or 0,
        chase_speed = tonumber(props.chase_speed) or -1,
        charge_speed = tonumber(props.charge_speed) or -1,
        charge_distance = tonumber(props.charge_distance) or -1,
        charge_telegraph_time = tonumber(props.charge_telegraph_time) or -1,
        charge_duration = tonumber(props.charge_duration) or -1,
        charge_cooldown = tonumber(props.charge_cooldown) or -1,
        charge_recovery = tonumber(props.charge_recovery) or -1,
        arena_id = props.arena_id or "",
        defeat_flag = props.defeat_flag or "",
        victory_music = optional_id(props.victory_music) or "",
        properties = props,
    })

    log_register("boss spawn", boss_id, world_x, world_y,
        string.format("(name: %s, preset: %s)", tostring(boss_name), tostring(boss_preset or "none")))
    return boss_id
end

--- Handle boss phase definition object
-- Tiled properties:
--   boss_id: string (links phase to a specific boss instance)
--   boss_preset: string (optional preset fallback)
--   arena_id: string (optional arena link)
--   phase: number (phase index starting at 1)
--   health_min / health_max: numbers (0.0 - 1.0)
--   attacks: string (CSV of attack pattern ids)
--   attack_interval_min / attack_interval_max: seconds
--   chase_speed: optional absolute chase speed (-1 inherits)
--   charge_*: optional phase-local charge tuning (-1 inherits)
--   behavior: string
--   speed_multiplier / damage_multiplier: numbers
--   transition_*: optional transition settings

function handlers.boss_phase(object, room_id)
    local props = get_props(object)
    local phase_id = make_id(props, "phase_id", "boss_phase", object, room_id)
    local boss_preset = resolve_boss_preset(props)

    msg.post("main:/main_go#script", hash("register_boss_phase"), {
        id = phase_id,
        boss_id = OP.get(props, "boss_id", ""),
        boss_preset = boss_preset or "",
        boss_type = boss_preset or "",
        arena_id = props.arena_id or "",
        room_id = room_id,
        phase = tonumber(props.phase) or 1,
        health_min = tonumber(props.health_min),
        health_max = tonumber(props.health_max),
        attacks = props.attacks or "",
        attack_interval_min = tonumber(props.attack_interval_min),
        attack_interval_max = tonumber(props.attack_interval_max),
        chase_speed = tonumber(props.chase_speed) or -1,
        charge_speed = tonumber(props.charge_speed) or -1,
        charge_distance = tonumber(props.charge_distance) or -1,
        charge_telegraph_time = tonumber(props.charge_telegraph_time) or -1,
        charge_duration = tonumber(props.charge_duration) or -1,
        charge_cooldown = tonumber(props.charge_cooldown) or -1,
        charge_recovery = tonumber(props.charge_recovery) or -1,
        behavior = props.behavior or "",
        speed_multiplier = tonumber(props.speed_multiplier),
        damage_multiplier = tonumber(props.damage_multiplier),
        transition_type = props.transition_type or "",
        transition_duration = tonumber(props.transition_duration),
        transition_iframes = tonumber(props.transition_iframes),
        transition_animation = props.transition_animation or "",
        transition_camera_intensity = tonumber(props.transition_camera_intensity),
        transition_camera_duration = tonumber(props.transition_camera_duration),
        transition_flash = props.transition_flash,
        transition_arena_darkness = props.transition_arena_darkness,
        transition_spawn_hazards = props.transition_spawn_hazards or "",
        transition_teleport_to = props.transition_teleport_to or "",
        transition_new_music = optional_id(props.transition_new_music) or "",
        properties = props,
    })

    log_register("boss phase", phase_id, object.x or 0, object.y or 0,
        string.format("(boss=%s phase=%s)", tostring(props.boss_id or boss_preset or ""), tostring(props.phase or 1)))
    return phase_id
end

--- Handle boss phase trigger object
-- Tiled properties:
--   boss_id: string (tag/id to find boss)
--   boss_preset: string (optional boss preset fallback)
--   arena_id: string (optional arena id)
--   phase: number (phase to force)
--   transition_time: number
--   trigger_once: bool
--   requires_flag: string
--   set_flag: string
--   delay: number

function handlers.boss_phase_trigger(object, room_id)
    local props = get_props(object)
    local trigger_id = make_id(props, "trigger_id", "boss_phase", object, room_id)
    local _, _, pos = world_rect(object, room_id, 128, 128)
    local boss_preset = resolve_boss_preset(props)

    local instance = spawn_factory("boss_phase_trigger_factory", pos, {
        boss_id = OP.get(props, "boss_id", ""),
        boss_type = boss_preset or "",
        arena_id = props.arena_id or "",
        phase = props.phase or 1,
        transition_time = props.transition_time or 0,
        trigger_once = to_bool(props.trigger_once, false),
        requires_flag = props.requires_flag or "",
        set_flag = props.set_flag or "",
        delay = props.delay or 0,
    }, 1, "boss phase trigger")

    if not instance then return nil end

    send_tiled_props(instance, props)

    apply_scale(instance, object.width or 128, object.height or 128, 64, 64, 128, 128)

    log_spawn("boss phase trigger", trigger_id, pos.x, pos.y)
    return instance
end

