--- Handle boss add spawner object
-- Tiled properties:
--   boss_id: string
--   boss_preset: string (optional boss preset fallback)
--   arena_id: string
--   enemy_type: string
--   spawn_interval: number
--   spawn_count: number
--   spawn_radius: number
--   max_alive: number
--   max_total: number
--   active_phases: string

function handlers.boss_add_spawner(object, room_id)
    local props = get_props(object)
    local spawner_id = non_empty_string(props.spawner_id)
        or non_empty_string(object.name)
        or string.format("boss_add_%s_%d", tostring(room_id), object.id)
    local _, _, pos = world_point(object, room_id)
    local boss_preset = resolve_boss_preset(props)

    local instance = spawn_factory("boss_add_spawner_factory", pos, {
        spawner_id = spawner_id,
        boss_id = OP.get(props, "boss_id", ""),
        boss_type = boss_preset or "",
        arena_id = props.arena_id or "",
        enemy_type = props.enemy_type or "slime",
        spawn_interval = props.spawn_interval or 4.0,
        spawn_count = props.spawn_count or 1,
        spawn_radius = props.spawn_radius or 120,
        max_alive = props.max_alive or 3,
        max_total = props.max_total or 0,
        active_phases = props.active_phases or "",
        start_delay = props.start_delay or 0,
        start_active = to_bool(props.start_active, true),
        health_mult = props.health_mult or 1.0,
        damage_mult = props.damage_mult or 1.0,
        speed_mult = props.speed_mult or 1.0,
        room_id = room_id,
    }, 1, "boss add spawner")

    if not instance then return nil end

    send_tiled_props(instance, props)

    log_spawn("boss add spawner", spawner_id, pos.x, pos.y)
    return instance
end

--- Register the boss arena's internal lock marker.
function handlers.arena_lock(object, room_id)
    local props = get_props(object)
    local arena_id = props.arena_id or string.format("arena_%s", room_id)
    local _, _, pos = world_point(object, room_id)
    local boss_preset = resolve_boss_preset(props)

    msg.post("main:/main_go#script", hash("register_arena_lock"), {
        id = object.id,
        arena_id = arena_id,
        position = pos,
        width = object.width or 64,
        height = object.height or 64,
        room_id = room_id,
        lock_on_enter = to_bool(props.lock_on_enter, true),
        unlock_on_clear = to_bool(props.unlock_on_clear, true),
        encounter_id = props.encounter_id,
        boss_id = props.boss_id,
        boss_tag = props.boss_tag,
        boss_preset = boss_preset,
        boss_type = boss_preset,
        charge_edge_padding = tonumber(props.charge_edge_padding) or -1,
        is_boss_arena = to_bool(props.is_boss_arena, false),
        properties = props,
    })

    log_register("arena lock", arena_id, pos.x, pos.y)
    return object.id
end

--- Handle boss arena definition.
-- Boss arenas own arena runtime configuration and also register an entry lock
-- zone so the fight can start from the same Tiled object.

function handlers.boss_arena(object, room_id)
    local props = get_props(object)
    props.is_boss_arena = to_bool(props.is_boss_arena, true)
    props.lock_on_enter = to_bool(props.lock_on_enter, true)
    props.unlock_on_clear = to_bool(props.unlock_on_clear, true)
    object.properties = props

    local _, _, center_pos, width, height = world_rect(object, room_id, 800, 600)
    local camera_lock = to_bool(props.camera_lock, false)
    local camera_zone_id = (props.arena_id and props.arena_id ~= "" and props.arena_id)
        or string.format("boss_cam_%s_%d", tostring(room_id), object.id)
    msg.post("main:/main_go#script", hash("register_camera_zone"), {
        id = camera_zone_id,
        position = vmath.vector3(center_pos.x - width * 0.5, center_pos.y - height * 0.5, 0),
        width = width,
        height = height,
        room_id = room_id,
        camera_mode = camera_lock and "fixed" or "follow",
        arena_auto_fit = camera_lock,
        fit_padding = 0,
        priority = tonumber(props.camera_priority) or 10,
    })

    local boss_arena = get_boss_arena()
    if boss_arena and boss_arena.create_from_tiled and boss_arena.setup_arena then
        local ok_cfg, config = pcall(boss_arena.create_from_tiled, props)
        if ok_cfg and type(config) == "table" then
            local bounds = {
                x = center_pos.x - width * 0.5,
                y = center_pos.y - height * 0.5,
                width = width,
                height = height,
            }
            config.bounds = bounds
            config.room_id = room_id
            config.boss_id = props.boss_id or config.boss_id
            config.boss_type = resolve_boss_preset(props) or config.boss_type
            local arena_id = props.arena_id or string.format("arena_%s", room_id)
            pcall(boss_arena.setup_arena, arena_id, config)
        end
    end

    return M.handlers.arena_lock(object, room_id)
end

