--- Handle player spawn point (where player appears in this room)
-- Tiled properties:
--   spawn_id: string (unique identifier for this spawn, e.g. "spawn_a", "spawn_entrance")
--   facing: number (1 = right, -1 = left)
--   default: bool (if true, this is the default spawn for this room)
--   from_room: string (only use this spawn when coming from specified room)
--   from_door: string (only use this spawn when coming from specified door)

    return handlers
end
